  Definition pass2_post (nc : Z) (R' : bvmap 5 word) (M' : mem) : Prop :=
    getr R' 10%bv = Z_to_bv 64 nc /\ 1 <= nc <= 21
    /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
    /\ stores_in (fun a => zwin (sp - 608) (sp + 96) a \/ zwin (sp + 368 + 40) (sp + 368 + 48) a) M M'
    /\ fld SEGS M' (sp + 368 + 40) 8 (sp + 16 + nc).

  Lemma tail_pos : forall R3 M3 m nd pl, stC R3 M3 m nd pl -> 0 < m ->
    exists nc R' M', msteps SEGS (@mkst fx R3 (Z_to_bv 64 IFMT_TAIL) M3 (seg_rom SEGS)) (@mkst fx R' (Z_to_bv 64 ret) M' (seg_rom SEGS)) /\ pass2_post nc R' M'.
Proof using fx RRND R M sp ret v Hret Hretr Hsp Hsplo Hsphi Hal HD Hv F3 ROC RRC FCAN.
